            sqrtOraclePrice,
            tradeResult,
            slippageTolerance,
            tradeParams.tradeAmountSqrt == 0 ? 0 : _MAX_ACCEPTABLE_SQRT_PRICE_RANGE
        );

        uint256 sentMarginAmount = 0;

        if (!hasPosition) {
            int256 remainingMargin = vault.margin;

            if (remainingMargin > 0) {
                if (vault.recipient != address(0)) {
                    // Send the remaining margin to the recipient.
                    vault.margin = 0;

                    sentMarginAmount = uint256(remainingMargin);

                    ERC20(pairStatus.quotePool.token).safeTransfer(vault.recipient, sentMarginAmount);
                }
            } else if (remainingMargin < 0) {
                vault.margin = 0;

                // To prevent the liquidator from unfairly profiting through arbitrage trades in the AMM and passing losses onto the protocol,
                // any losses that cannot be covered by the vault must be compensated by the liquidator
                ERC20(pairStatus.quotePool.token).safeTransferFrom(msg.sender, address(this), uint256(-remainingMargin));
            }
        }

        emit PositionLiquidated(
            tradeParams.vaultId,
            tradeParams.pairId,
            tradeParams.tradeAmount,
            tradeParams.tradeAmountSqrt,
            tradeResult.payoff,
            tradeResult.fee,
            sentMarginAmount
        );
    }

```

## Impact
The impact of this issue is significant as it directly affects the core functionality of the protocol—liquidating under-collateralized vaults to maintain system stability. If a token used as collateral is paused, the `execLiquidationCall` function will revert, preventing the liquidation process. This means that vaults in a dangerous state cannot be liquidated, which can lead to a loss of funds for users and potential insolvency of the protocol.

## Likelihood: 
The likelihood of this issue occurring is medium to high, particularly for tokens that are frequently paused due to regulatory concerns or other operational issues (such as USDC or USDT). Given the prevalence of these tokens in DeFi applications, the risk of encountering a paused token during critical operations is non-negligible.

